# يولّد أيقونة التطبيق (جدولي) داخل مشروع أندرويد
import base64, io, os, subprocess, sys
try:
    from PIL import Image
except ImportError:
    subprocess.check_call([sys.executable, "-m", "pip", "install", "--break-system-packages", "pillow"])
    from PIL import Image

B64 = ""

im = Image.open(io.BytesIO(base64.b64decode(B64))).convert("RGBA")
res = "android/app/src/main/res"
for d, n in (("mdpi", 48), ("hdpi", 72), ("xhdpi", 96), ("xxhdpi", 144), ("xxxhdpi", 192)):
    p = os.path.join(res, "mipmap-" + d)
    os.makedirs(p, exist_ok=True)
    im.resize((n, n), Image.LANCZOS).save(os.path.join(p, "ic_launcher.png"))

# أيقونة الإشعار (جرس أحادي اللون)
os.makedirs(os.path.join(res, "drawable"), exist_ok=True)
open(os.path.join(res, "drawable", "ic_stat.xml"), "w").write(
    '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">'
    '<path android:fillColor="#FFFFFFFF" android:pathData="M12,22c1.1,0 2,-0.9 2,-2h-4c0,1.1 0.9,2 2,2zM18,16v-5c0,-3.07 -1.63,-5.64 -4.5,-6.32V4c0,-0.83 -0.67,-1.5 -1.5,-1.5s-1.5,0.67 -1.5,1.5v0.68C7.64,5.36 6,7.92 6,11v5l-2,2v1h16v-1l-2,-2z"/>'
    '</vector>'
)
print("icons done")
